// Shared ocean wave math. The same constants drive the GLSL displacement in
// ocean.js and the CPU sampling used to place the pelican on the water, so the
// bird always sits exactly on the surface.

export const WAVE = {
  a1: 1.4, k1: 0.08, w1: 0.8, // long swell along X
  a2: 0.9, k2: 0.11, w2: 0.6, // swell along Z
  a3: 1.2, k3: 0.05, w3: 0.5, // diagonal swell
  a4: 0.35, k4: 0.21, w4: 1.3, // small ripple X
  a5: 0.25, k5: 0.27, w5: 1.7, // small ripple Z
};

const f = (v) => Number(v).toFixed(8);

// GLSL twin of waveHeight() below. Expects a `uniform float uTime;` in scope.
export const waveGLSL = /* glsl */ `
float waveHeight(vec2 p) {
  float t = uTime;
  return ${f(WAVE.a1)} * sin(${f(WAVE.k1)} * p.x + ${f(WAVE.w1)} * t)
       + ${f(WAVE.a2)} * sin(${f(WAVE.k2)} * p.y - ${f(WAVE.w2)} * t)
       + ${f(WAVE.a3)} * sin(${f(WAVE.k3)} * (p.x + p.y) + ${f(WAVE.w3)} * t)
       + ${f(WAVE.a4)} * sin(${f(WAVE.k4)} * p.x - ${f(WAVE.w4)} * t)
       + ${f(WAVE.a5)} * sin(${f(WAVE.k5)} * p.y + ${f(WAVE.w5)} * t);
}
`;

export function waveHeight(x, z, t) {
  return (
    WAVE.a1 * Math.sin(WAVE.k1 * x + WAVE.w1 * t) +
    WAVE.a2 * Math.sin(WAVE.k2 * z - WAVE.w2 * t) +
    WAVE.a3 * Math.sin(WAVE.k3 * (x + z) + WAVE.w3 * t) +
    WAVE.a4 * Math.sin(WAVE.k4 * x - WAVE.w4 * t) +
    WAVE.a5 * Math.sin(WAVE.k5 * z + WAVE.w5 * t)
  );
}

// Analytic surface normal via partial derivatives of the wave sum.
export function waveNormal(x, z, t, out) {
  const dhdx =
    WAVE.a1 * WAVE.k1 * Math.cos(WAVE.k1 * x + WAVE.w1 * t) +
    WAVE.a3 * WAVE.k3 * Math.cos(WAVE.k3 * (x + z) + WAVE.w3 * t) +
    WAVE.a4 * WAVE.k4 * Math.cos(WAVE.k4 * x - WAVE.w4 * t);
  const dhdz =
    WAVE.a2 * WAVE.k2 * Math.cos(WAVE.k2 * z - WAVE.w2 * t) +
    WAVE.a3 * WAVE.k3 * Math.cos(WAVE.k3 * (x + z) + WAVE.w3 * t) +
    WAVE.a5 * WAVE.k5 * Math.cos(WAVE.k5 * z + WAVE.w5 * t);
  return out.set(-dhdx, 1, -dhdz).normalize();
}

import * as THREE from 'three';
import { waveGLSL } from './waves.js';

// A GPU-displaced ocean plane. The mesh stays at the origin and is panned in
// the vertex shader by `uOffset`, so the water is effectively endless.

const SIZE = 620;
const SEGMENTS = 300;
const SNAP = SIZE / SEGMENTS;

const vertexShader = /* glsl */ `
  uniform float uTime;
  uniform vec2 uOffset;

  varying vec3 vWorld;
  varying vec3 vNormal;
  varying float vWave;

  ${waveGLSL}

  void main() {
    vec2 world = position.xz + uOffset;
    float h = waveHeight(world);
    vWave = h;

    vec3 pos = position;
    pos.x += uOffset.x;
    pos.z += uOffset.y;
    pos.y = h;

    // Surface normal from finite differences of the same wave function.
    float e = 0.45;
    float hL = waveHeight(world - vec2(e, 0.0));
    float hR = waveHeight(world + vec2(e, 0.0));
    float hD = waveHeight(world - vec2(0.0, e));
    float hU = waveHeight(world + vec2(0.0, e));
    vNormal = normalize(vec3(hL - hR, 2.0 * e, hD - hU));

    vec4 wp = modelMatrix * vec4(pos, 1.0);
    vWorld = wp.xyz;

    gl_Position = projectionMatrix * viewMatrix * wp;
  }
`;

const fragmentShader = /* glsl */ `
  uniform float uTime;
  uniform vec3 uDeep;
  uniform vec3 uShallow;
  uniform vec3 uSky;
  uniform vec3 uHorizon;
  uniform vec3 uSunDir;
  uniform vec3 uCamPos;

  varying vec3 vWorld;
  varying vec3 vNormal;
  varying float vWave;

  void main() {
    vec3 N = normalize(vNormal);
    vec3 V = normalize(uCamPos - vWorld);

    float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 3.0);

    vec3 base = mix(uDeep, uShallow, smoothstep(-1.5, 2.6, vWave));
    vec3 col = mix(base, uSky, fres * 0.85);

    // Sun glint.
    vec3 L = normalize(uSunDir);
    vec3 H = normalize(L + V);
    float spec = pow(max(dot(N, H), 0.0), 220.0);
    col += vec3(1.0, 0.94, 0.82) * spec * 1.8;

    // Translucent glow on the wave crests.
    float crest = smoothstep(1.0, 2.4, vWave);
    col += uShallow * crest * 0.55;

    // Foam near the highest crests, broken up by a bit of procedural noise.
    float foam = smoothstep(1.95, 2.7, vWave);
    float n = sin(vWorld.x * 2.7 + uTime * 1.7) *
              sin(vWorld.z * 3.3 - uTime * 2.1);
    foam *= 0.55 + 0.45 * (n * 0.5 + 0.5);
    col = mix(col, vec3(0.93, 0.98, 1.0), foam * 0.85);

    // Fade into the horizon color with distance.
    float d = length(uCamPos - vWorld);
    col = mix(col, uHorizon, smoothstep(130.0, 380.0, d));

    gl_FragColor = vec4(col, 1.0);
  }
`;

export function createOcean() {
  const geometry = new THREE.PlaneGeometry(SIZE, SIZE, SEGMENTS, SEGMENTS);
  geometry.rotateX(-Math.PI / 2);

  const uniforms = {
    uTime: { value: 0 },
    uOffset: { value: new THREE.Vector2() },
    uDeep: { value: new THREE.Color(0x06283a) },
    uShallow: { value: new THREE.Color(0x0f7186) },
    uSky: { value: new THREE.Color(0xa8d6ee) },
    uHorizon: { value: new THREE.Color(0xcfe8f2) },
    uSunDir: { value: new THREE.Vector3(0.5, 0.45, -0.72).normalize() },
    uCamPos: { value: new THREE.Vector3() },
  };

  const material = new THREE.ShaderMaterial({
    uniforms,
    vertexShader,
    fragmentShader,
    side: THREE.FrontSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;

  return {
    mesh,
    uniforms,
    update(time, cameraPos) {
      uniforms.uTime.value = time;
      uniforms.uOffset.value.set(
        Math.round(cameraPos.x / SNAP) * SNAP,
        Math.round(cameraPos.z / SNAP) * SNAP,
      );
      uniforms.uCamPos.value.copy(cameraPos);
    },
  };
}

import * as THREE from 'three';

// All pelican geometry is generated in code -- no external assets. The bird is
// modelled in a local space where +X is forward (the direction of travel),
// +Y is up and +Z is to the rider's left.

function makeFeatherTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 256;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#f8f9f7';
  ctx.fillRect(0, 0, 256, 256);

  const img = ctx.getImageData(0, 0, 256, 256);
  for (let i = 0; i < img.data.length; i += 4) {
    const n = (Math.random() * 16) | 0;
    img.data[i] = Math.max(0, img.data[i] - n);
    img.data[i + 1] = Math.max(0, img.data[i + 1] - n);
    img.data[i + 2] = Math.max(0, img.data[i + 2] - n);
  }
  ctx.putImageData(img, 0, 0);

  // Soft feather streaks.
  ctx.globalAlpha = 0.06;
  ctx.strokeStyle = '#9fb0bd';
  for (let i = 0; i < 90; i++) {
    const y = Math.random() * 256;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.bezierCurveTo(80, y + 12, 170, y - 12, 256, y);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(2, 2);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

function makeWingGeometry() {
  const s = new THREE.Shape();
  s.moveTo(0, 0.2);
  s.bezierCurveTo(0.38, 0.3, 0.86, 0.2, 1.18, -0.04);
  s.bezierCurveTo(0.82, -0.12, 0.34, -0.3, 0, -0.24);
  s.closePath();

  const geo = new THREE.ExtrudeGeometry(s, {
    depth: 0.05,
    bevelEnabled: true,
    bevelThickness: 0.015,
    bevelSize: 0.02,
    bevelSegments: 2,
    curveSegments: 12,
  });
  // Lay the wing flat (chord across Z, span along X).
  geo.rotateX(-Math.PI / 2);
  geo.translate(0, 0, 0);
  return geo;
}

function makeBoardGeometry() {
  const s = new THREE.Shape();
  s.moveTo(-1.7, 0);
  s.bezierCurveTo(-1.0, 0.42, 0.9, 0.46, 1.7, 0);
  s.bezierCurveTo(0.9, -0.46, -1.0, -0.42, -1.7, 0);

  const geo = new THREE.ExtrudeGeometry(s, {
    depth: 0.12,
    bevelEnabled: true,
    bevelThickness: 0.03,
    bevelSize: 0.03,
    bevelSegments: 3,
    curveSegments: 18,
  });
  geo.rotateX(-Math.PI / 2);
  return geo;
}

export function createPelican() {
  const root = new THREE.Group();

  const featherMap = makeFeatherTexture();
  const mats = {
    feather: new THREE.MeshStandardMaterial({
      color: 0xffffff,
      map: featherMap,
      roughness: 0.78,
      metalness: 0.0,
    }),
    wingTip: new THREE.MeshStandardMaterial({
      color: 0x3a4048,
      roughness: 0.85,
    }),
    beak: new THREE.MeshStandardMaterial({ color: 0xf2a235, roughness: 0.35 }),
    pouch: new THREE.MeshStandardMaterial({
      color: 0xf6b56b,
      roughness: 0.5,
      transparent: true,
      opacity: 0.97,
    }),
    eye: new THREE.MeshStandardMaterial({ color: 0x0a0a10, roughness: 0.15 }),
    leg: new THREE.MeshStandardMaterial({ color: 0xef8a2b, roughness: 0.5 }),
    board: new THREE.MeshStandardMaterial({ color: 0xff6f52, roughness: 0.3 }),
    stripe: new THREE.MeshStandardMaterial({ color: 0xfff4d6, roughness: 0.3 }),
  };

  // ---- Surfboard -----------------------------------------------------------
  const board = new THREE.Mesh(makeBoardGeometry(), mats.board);
  board.position.y = 0.02;
  root.add(board);

  const stripe = new THREE.Mesh(
    new THREE.BoxGeometry(2.75, 0.02, 0.13),
    mats.stripe,
  );
  stripe.position.set(0, 0.17, 0);
  root.add(stripe);

  // ---- Legs & feet ---------------------------------------------------------
  for (const side of [-1, 1]) {
    const leg = new THREE.Mesh(
      new THREE.CylinderGeometry(0.045, 0.055, 0.46, 10),
      mats.leg,
    );
    leg.position.set(-0.02, 0.4, side * 0.15);
    root.add(leg);

    const foot = new THREE.Mesh(
      new THREE.BoxGeometry(0.3, 0.045, 0.16),
      mats.leg,
    );
    foot.position.set(0.04, 0.19, side * 0.15);
    root.add(foot);
  }

  // ---- Torso (everything above the legs) -----------------------------------
  const torso = new THREE.Group();
  root.add(torso);

  const body = new THREE.Mesh(new THREE.SphereGeometry(0.5, 32, 24), mats.feather);
  body.scale.set(1.2, 0.95, 0.92);
  body.position.set(-0.05, 0.95, 0);
  torso.add(body);

  const tail = new THREE.Mesh(new THREE.ConeGeometry(0.3, 0.62, 6), mats.feather);
  tail.rotation.z = 1.35; // point back and slightly up
  tail.scale.z = 0.6;
  tail.position.set(-0.72, 1.02, 0);
  torso.add(tail);

  const neckCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(0.28, 1.2, 0),
    new THREE.Vector3(0.42, 1.55, 0),
    new THREE.Vector3(0.55, 1.86, 0),
    new THREE.Vector3(0.62, 2.08, 0),
  ]);
  const neck = new THREE.Mesh(
    new THREE.TubeGeometry(neckCurve, 28, 0.16, 12, false),
    mats.feather,
  );
  torso.add(neck);

  const head = new THREE.Mesh(new THREE.SphereGeometry(0.3, 32, 24), mats.feather);
  head.scale.set(1.05, 0.95, 0.92);
  head.position.set(0.66, 2.12, 0);
  torso.add(head);

  // Upper mandible.
  const beak = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.82, 4), mats.beak);
  beak.rotation.z = -Math.PI / 2;
  beak.rotation.y = Math.PI / 4;
  beak.scale.set(0.85, 1.0, 0.7);
  beak.position.set(1.33, 2.11, 0);
  torso.add(beak);

  // Gular pouch.
  const pouch = new THREE.Mesh(new THREE.SphereGeometry(0.22, 24, 16), mats.pouch);
  pouch.scale.set(1.75, 1.25, 0.85);
  pouch.position.set(1.14, 1.99, 0);
  torso.add(pouch);

  for (const side of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.055, 16, 12), mats.eye);
    eye.position.set(0.84, 2.22, side * 0.2);
    torso.add(eye);
  }

  // ---- Wings ---------------------------------------------------------------
  const wingGeo = makeWingGeometry();
  const wings = [];
  for (const side of [-1, 1]) {
    const pivot = new THREE.Group();
    pivot.position.set(0.02, 1.14, side * 0.3);
    torso.add(pivot);

    const wing = new THREE.Mesh(wingGeo, mats.feather);
    pivot.add(wing);

    // Dark wing tips.
    const tip = new THREE.Mesh(new THREE.SphereGeometry(0.16, 12, 10), mats.wingTip);
    tip.scale.set(0.55, 0.22, 0.9);
    tip.position.set(1.1, 0, -0.02);
    pivot.add(tip);

    // Point the span outward, back and up.
    const dir = new THREE.Vector3(-0.45, 0.42, side * 0.85).normalize();
    const base = new THREE.Quaternion().setFromUnitVectors(
      new THREE.Vector3(1, 0, 0),
      dir,
    );
    pivot.quaternion.copy(base);

    wings.push({ pivot, base, side });
  }

  return { root, torso, wings };
}

import * as THREE from 'three';

function makeSprayTexture() {
  const size = 64;
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(
    size / 2, size / 2, 0,
    size / 2, size / 2, size / 2,
  );
  g.addColorStop(0.0, 'rgba(255,255,255,1)');
  g.addColorStop(0.4, 'rgba(255,255,255,0.75)');
  g.addColorStop(1.0, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

// CPU particle system for the bow spray thrown up by the board.
export class Spray {
  constructor(scene, max = 700) {
    this.max = max;
    this.pos = new Float32Array(max * 3);
    this.vel = new Float32Array(max * 3);
    this.life = new Float32Array(max);
    this.maxLife = new Float32Array(max);
    this.size = new Float32Array(max);
    this.alpha = new Float32Array(max);
    this.cursor = 0;
    this.emitAcc = 0;

    for (let i = 0; i < max; i++) this.pos[i * 3 + 1] = -9999;

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alpha, 1));

    const mat = new THREE.ShaderMaterial({
      uniforms: { uTex: { value: makeSprayTexture() } },
      vertexShader: /* glsl */ `
        attribute float aSize;
        attribute float aAlpha;
        varying float vAlpha;
        void main() {
          vAlpha = aAlpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = aSize * (280.0 / max(-mv.z, 0.1));
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: /* glsl */ `
        uniform sampler2D uTex;
        varying float vAlpha;
        void main() {
          vec4 t = texture2D(uTex, gl_PointCoord);
          gl_FragColor = vec4(0.92, 0.97, 1.0, t.a * vAlpha);
        }
      `,
      transparent: true,
      depthWrite: false,
      blending: THREE.NormalBlending,
    });

    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    scene.add(this.points);
  }

  spawn(origin, back, up, right, dt) {
    this.emitAcc += dt * 190;
    while (this.emitAcc >= 1) {
      this.emitAcc -= 1;
      const i = this.cursor;
      this.cursor = (this.cursor + 1) % this.max;

      const spread = 0.55;
      this.pos[i * 3 + 0] = origin.x + (Math.random() - 0.5) * spread;
      this.pos[i * 3 + 1] = origin.y + Math.random() * 0.15;
      this.pos[i * 3 + 2] = origin.z + (Math.random() - 0.5) * spread;

      const bs = 2.5 + Math.random() * 3.5;
      const us = 2.0 + Math.random() * 3.5;
      const rs = (Math.random() - 0.5) * 3.0;
      this.vel[i * 3 + 0] = back.x * bs + up.x * us + right.x * rs;
      this.vel[i * 3 + 1] = back.y * bs + up.y * us + right.y * rs;
      this.vel[i * 3 + 2] = back.z * bs + up.z * us + right.z * rs;

      const life = 0.7 + Math.random() * 0.9;
      this.life[i] = life;
      this.maxLife[i] = life;
      this.size[i] = 0.35 + Math.random() * 0.8;
    }
  }

  update(dt) {
    const gravity = -5.2;
    for (let i = 0; i < this.max; i++) {
      if (this.life[i] <= 0) {
        this.alpha[i] = 0;
        continue;
      }
      this.life[i] -= dt;
      if (this.life[i] <= 0) {
        this.alpha[i] = 0;
        this.pos[i * 3 + 1] = -9999;
        continue;
      }
      this.vel[i * 3 + 1] += gravity * dt;
      this.pos[i * 3 + 0] += this.vel[i * 3 + 0] * dt;
      this.pos[i * 3 + 1] += this.vel[i * 3 + 1] * dt;
      this.pos[i * 3 + 2] += this.vel[i * 3 + 2] * dt;

      const t = this.life[i] / this.maxLife[i];
      this.alpha[i] = Math.min(1, t * 1.8) * (0.25 + 0.75 * t);
    }

    this.points.geometry.attributes.position.needsUpdate = true;
    this.points.geometry.attributes.aSize.needsUpdate = true;
    this.points.geometry.attributes.aAlpha.needsUpdate = true;
  }
}

import * as THREE from 'three';

// Procedural sky, clouds and distant birds. Everything is drawn on canvases at
// runtime so the page needs no external assets.

function makeSkyTexture() {
  const w = 2048;
  const h = 1024;
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const ctx = c.getContext('2d');

  const g = ctx.createLinearGradient(0, 0, 0, h);
  g.addColorStop(0.0, '#0a2450');
  g.addColorStop(0.3, '#2b6cae');
  g.addColorStop(0.48, '#7fbde5');
  g.addColorStop(0.56, '#d7eefb');
  g.addColorStop(0.62, '#cfe8f2');
  g.addColorStop(1.0, '#8fc0d0');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);

  // Sun glow.
  const sunX = w * 0.68;
  const sunY = h * 0.5;
  const sg = ctx.createRadialGradient(sunX, sunY, 0, sunX, sunY, 320);
  sg.addColorStop(0.0, 'rgba(255,255,245,0.95)');
  sg.addColorStop(0.12, 'rgba(255,244,214,0.75)');
  sg.addColorStop(0.45, 'rgba(255,232,190,0.18)');
  sg.addColorStop(1.0, 'rgba(255,232,190,0)');
  ctx.fillStyle = sg;
  ctx.fillRect(0, 0, w, h);

  // Clouds -- layered soft ellipses in a band above the horizon.
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 46; i++) {
    const cx = Math.random() * w;
    const cy = h * (0.22 + Math.random() * 0.26);
    const scale = 0.5 + Math.random();
    const puffs = 6 + ((Math.random() * 6) | 0);
    for (let p = 0; p < puffs; p++) {
      const rx = (60 + Math.random() * 120) * scale;
      const ry = rx * (0.35 + Math.random() * 0.25);
      const ox = (Math.random() - 0.5) * 320 * scale;
      const oy = (Math.random() - 0.5) * 60 * scale;
      const a = 0.02 + Math.random() * 0.05;
      const cg = ctx.createRadialGradient(cx + ox, cy + oy, 0, cx + ox, cy + oy, rx);
      cg.addColorStop(0, `rgba(255,255,255,${a})`);
      cg.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = cg;
      ctx.save();
      ctx.translate(cx + ox, cy + oy);
      ctx.scale(1, ry / rx);
      ctx.beginPath();
      ctx.arc(0, 0, rx, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
  }
  ctx.globalCompositeOperation = 'source-over';

  const tex = new THREE.CanvasTexture(c);
  tex.mapping = THREE.EquirectangularReflectionMapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function makeCloudTexture() {
  const s = 128;
  const c = document.createElement('canvas');
  c.width = c.height = s;
  const ctx = c.getContext('2d');
  for (let i = 0; i < 14; i++) {
    const x = s / 2 + (Math.random() - 0.5) * 60;
    const y = s / 2 + (Math.random() - 0.5) * 34;
    const r = 16 + Math.random() * 24;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, 'rgba(255,255,255,0.5)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function createEnvironment(scene, renderer) {
  const skyTex = makeSkyTexture();
  scene.background = skyTex;

  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromEquirectangular(skyTex).texture;
  pmrem.dispose();

  const sunDir = new THREE.Vector3(0.5, 0.45, -0.72).normalize();

  const sun = new THREE.DirectionalLight(0xfff3dd, 2.1);
  sun.position.copy(sunDir).multiplyScalar(60);
  scene.add(sun);

  const fill = new THREE.HemisphereLight(0xbfe3ff, 0x1a4a55, 1.15);
  scene.add(fill);

  // Billboard clouds for depth.
  const cloudTex = makeCloudTexture();
  const clouds = [];
  const cloudMat = new THREE.SpriteMaterial({
    map: cloudTex,
    transparent: true,
    depthWrite: false,
    opacity: 0.85,
  });
  for (let i = 0; i < 14; i++) {
    const sprite = new THREE.Sprite(cloudMat.clone());
    const s = 14 + Math.random() * 26;
    sprite.scale.set(s * 1.8, s, 1);
    sprite.position.set(
      (Math.random() - 0.5) * 320,
      32 + Math.random() * 46,
      (Math.random() - 0.5) * 320 - 60,
    );
    sprite.material.opacity = 0.4 + Math.random() * 0.4;
    clouds.push({ sprite, speed: 0.6 + Math.random() * 1.1 });
    scene.add(sprite);
  }

  return {
    sunDir,
    update(dt) {
      for (const c of clouds) {
        c.sprite.position.x -= c.speed * dt;
        if (c.sprite.position.x < -190) c.sprite.position.x = 190;
      }
    },
  };
}

// A few distant gulls for scale and life.
export function createBirds(scene, count = 7) {
  const birds = [];
  const mat = new THREE.MeshStandardMaterial({
    color: 0xf3f5f7,
    roughness: 0.9,
    side: THREE.DoubleSide,
  });

  const wingShape = new THREE.Shape();
  wingShape.moveTo(0, 0);
  wingShape.lineTo(1.0, 0.16);
  wingShape.lineTo(1.0, -0.16);
  wingShape.closePath();
  const wingGeo = new THREE.ShapeGeometry(wingShape);

  for (let i = 0; i < count; i++) {
    const bird = new THREE.Group();
    const body = new THREE.Mesh(new THREE.SphereGeometry(0.16, 10, 8), mat);
    body.scale.set(1.9, 0.8, 0.8);
    bird.add(body);

    const wingL = new THREE.Mesh(wingGeo, mat);
    wingL.rotation.y = Math.PI / 2;
    bird.add(wingL);
    const wingR = new THREE.Mesh(wingGeo, mat);
    wingR.rotation.y = -Math.PI / 2;
    bird.add(wingR);

    const radius = 70 + Math.random() * 90;
    const phase = Math.random() * Math.PI * 2;
    bird.position.set(
      Math.cos(phase) * radius,
      24 + Math.random() * 24,
      Math.sin(phase) * radius,
    );
    const s = 0.8 + Math.random() * 0.7;
    bird.scale.setScalar(s);
    scene.add(bird);

    birds.push({
      bird,
      wingL,
      wingR,
      phase,
      radius,
      speed: (0.05 + Math.random() * 0.05) * (Math.random() < 0.5 ? -1 : 1),
      flap: 3 + Math.random() * 2,
      flapPhase: Math.random() * Math.PI * 2,
    });
  }

  return {
    update(t) {
      for (const b of birds) {
        b.phase += b.speed * 0.01;
        b.bird.position.x = Math.cos(b.phase) * b.radius;
        b.bird.position.z = Math.sin(b.phase) * b.radius;
        b.bird.rotation.y = -b.phase + Math.PI / 2;
        const f = Math.sin(t * b.flap + b.flapPhase) * 0.55;
        b.wingL.rotation.z = f;
        b.wingR.rotation.z = -f;
      }
    },
  };
}

